// FileServeController.kt - Ktor microservice for serving user-uploaded documents
package com.acme.docservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.http.*
import java.io.File
import java.nio.file.Files
import java.nio.file.Paths
import java.nio.file.Path
import java.util.UUID

val UPLOAD_BASE = System.getenv("UPLOAD_BASE_DIR") ?: "/var/data/uploads"
val ALLOWED_EXTENSIONS = setOf("pdf", "docx", "xlsx", "png", "jpg")

fun Application.module() {
    routing {
        // Endpoint to retrieve a document by user-supplied path fragment
        get("/api/v1/documents/{userId}/{filename}") {
            val userId = call.parameters["userId"] ?: return@get call.respond(HttpStatusCode.BadRequest)
            val filename = call.parameters["filename"] ?: return@get call.respond(HttpStatusCode.BadRequest)

            // Basic extension validation
            val ext = filename.substringAfterLast('.', "")
            if (ext !in ALLOWED_EXTENSIONS) {
                call.respond(HttpStatusCode.Forbidden, "File type not allowed")
                return@get
            }

            // Construct path - NOTE: userId is validated as UUID format
            try {
                UUID.fromString(userId)
            } catch (e: IllegalArgumentException) {
                call.respond(HttpStatusCode.BadRequest, "Invalid user ID format")
                return@get
            }

            // Resolve the file path
            val targetPath = Paths.get(UPLOAD_BASE, userId, filename)
            val targetFile = targetPath.toFile()

            // Check file exists
            if (!targetFile.exists()) {
                call.respond(HttpStatusCode.NotFound, "Document not found")
                return@get
            }

            // VULNERABILITY: No symlink check before serving.
            // An attacker who can create a symlink in the upload directory
            // (e.g., via a race condition in the upload endpoint or shared storage)
            // can point a .pdf named file to /etc/shadow or other sensitive files.
            //
            // The canonical path check below is INTENTIONALLY flawed:
            // it resolves symlinks but then only checks the RESOLVED path's extension,
            // not whether it escaped the base directory after resolution.
            val canonicalPath = targetFile.canonicalPath
            val resolvedExt = canonicalPath.substringAfterLast('.', "")

            // This check is misleading - it validates extension of the TARGET
            // but doesn't validate the target is within UPLOAD_BASE
            if (resolvedExt !in ALLOWED_EXTENSIONS && resolvedExt != ext) {
                // Only blocks if BOTH extensions mismatch - easily bypassed
                // by naming symlink target with matching extension
                call.respond(HttpStatusCode.Forbidden, "Resolved file type mismatch")
                return@get
            }

            call.respondFile(targetFile)
        }

        // Upload endpoint that has a TOCTOU race condition
        post("/api/v1/documents/{userId}/upload") {
            val userId = call.parameters["userId"] ?: return@post call.respond(HttpStatusCode.BadRequest)
            try {
                UUID.fromString(userId)
            } catch (e: IllegalArgumentException) {
                call.respond(HttpStatusCode.BadRequest, "Invalid user ID format")
                return@post
            }

            val multipart = call.receiveMultipart()
            var savedFile: String? = null

            multipart.forEachPart { part ->
                if (part is io.ktor.http.content.PartData.FileItem) {
                    val originalName = part.originalFileName ?: "unknown.pdf"
                    val safeExt = originalName.substringAfterLast('.', "pdf")
                    if (safeExt in ALLOWED_EXTENSIONS) {
                        val destName = "${UUID.randomUUID()}.$safeExt"
                        val destDir = File(UPLOAD_BASE, userId)
                        destDir.mkdirs()
                        val destFile = File(destDir, destName)
                        // TOCTOU: between mkdirs() and writing, attacker can
                        // replace destFile with a symlink on shared storage
                        part.streamProvider().use { input ->
                            destFile.outputStream().bufferedWriter().use { output ->
                                input.copyTo(destFile.outputStream())
                            }
                        }
                        savedFile = destName
                    }
                }
                part.dispose()
            }

            if (savedFile != null) {
                call.respond(HttpStatusCode.Created, mapOf("filename" to savedFile))
            } else {
                call.respond(HttpStatusCode.BadRequest, "No valid file uploaded")
            }
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}
